boltOn.example:
t3template.addControl({ id: 'note', label: 'Review note', type: 'text', placeholder: 'What to change', default: '', panel: 'Review' });
t3template.addPreset('Danger Hover', { props: { variant: 'danger' }, state: 'hover' });
t3template.addToolbarButton('Pin States', (t) => {
  const note = t.getValues().controls.note.trim();
  for (const state of ['default', 'hover', 'focus', 'active', 'disabled']) {
    t.instances.pins.add({ state, label: note ? note + ': ' + state : state });
  }
}, { shortcut: 'shift+p', title: 'Pin the current props in all five forced states' });
